# -*- coding: utf-8 -*-
import re
p='src/lalka-2/work/chapter-01/scaffold.txt'
t={325:'— Кажу «колега», бо ми обоє бачили за кордоном однаково цікаві речі.',326:'— Шановний пан був за кордоном? О, треба ж!... — озвалася старенька.',327:'— У 1849 році й трохи пізніше, — втрутився я.',328:'— А чи не траплялося шановному панові десь зустріти Людвіка Ставського?',329:'— Та що ви, пані добродійко! — вигукнув Вірський, сміючись і вклоняючись. — Пан Ржецький був за кордоном тридцять років тому, а ваш зять виїхав лише чотири роки тому...',330:'Старенька махнула рукою, наче відганяла муху.',331:'— Правда! — сказала вона. — Що це я верзу... Та я весь час думаю про Людвичка... Прошу панів сісти...',332:'Ми сіли, і екс-поміщик знову вклонився поважній пані, а вона — йому.',333:'Тільки тепер я помітив, що попеляста сукня старенької в багатьох місцях полатана, й мене охопила дивна туга, коли я побачив цих двох людей — його в забрудненому сюртуці, її в латаній сукні, — які поводилися, мов князі. Над ними вже пройшов плуг часу, що все зрівнює.',334:'— Певно, пан не знає про наше горе, — сказала поважна пані, звертаючись до мене. — Чотири роки тому з моїм зятем трапилася дуже прикра історія, і цілком несправедливо... Тут убили якусь страшну лихварку... Ах, Боже! Нема про що й говорити...',335:'Досить сказати, що хтось із близьких попередив його, що підозра падає на нього... Зовсім невинно, пане...',336:'— Ржецький, — втрутився екс-поміщик.',337:'— Найбільш несправедливо, пане Ржецький... І він, бідолаха, втік за кордон. Минулого року знайшли справжнього вбивцю, Людвіка оголосили невинним, але що з того, коли він уже два роки не писав...',338:'Тут вона нахилилася до мене з крісла й прошепотіла:',339:'— Геленка, моя донька, пане...',340:'— Ржецький, — озвався управитель.',341:'— Моя донька, пане Ржецький, розоряється... Щиро кажу, витрачається на оголошення в закордонних газетах, а відповіді немає й немає... Вона молода жінка, пане...',342:'— Ржецький, — промовив Вірський.',343:'— Молода жінка, пане Ржецький, і вродлива.',344:'— Надзвичайно вродлива! — із запалом додав управитель.'}
ls=open(p,encoding='utf-8').read().splitlines();i=-1;o=[]
for l in ls:
 if l.startswith('**PL:**'):i+=1
 if l=='**UA:**' and i in t:l='**UA:** '+t[i]
 o.append(l)
open(p,'w',encoding='utf-8').write('\n'.join(o));print('filled',len(t))
